func main() {
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		log.Fatal(err)
	}

	ec2Svc := ec2.New(sess)

	// Define the tag name and values
	tagName := "backup_type"

	// Define the retention policies
	retentionPolicies := map[string]int{
		"monthly":   14,
		"daily":     10,
		"weekly":    4,
		"yearly":    1,
	}

	// Get all EBS Snapshots
	input := &ec2.DescribeSnapshotsInput{}
	snapshots, err := ec2Svc.DescribeSnapshots(context.Background(), input)
	if err != nil {
		log.Fatal(err)
	}

	// Iterate through the snapshots and delete those that exceed the retention policies
	for _, snapshot := range snapshots.Snapshots {
		tag, ok := snapshot.Tags[tagName]
		if !ok {
			continue
		}

		// Determine the retention policy for this snapshot
		retentionPolicy, ok := retentionPolicies[tag.Value]
		if !ok {
			continue
		}

		// Delete the snapshot if it exceeds the retention policy
		if isExceededRetentionPolicy(snapshot, retentionPolicy, tagName) {
			_, err := ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: aws.String(snapshot.SnapshotId)})
			if err != nil {
				log.Println(err)
			}
		}
	}

	log.Println("Completed snapshot cleanup")
}

func isExceededRetentionPolicy(snapshot *ec2.Snapshot, retentionPolicy int, tagName string) bool {
	// Determine the snapshot's age based on its start time
	startTime, err := time.Parse("2006-01-02T15:04:05Z", *snapshot.StartTime)
	if err != nil {
		log.Fatal(err)
	}
	age := time.Since(startTime)

	// Determine the retention policy to apply
	switch *snapshot.Tags[tagName].Value {
	case "monthly":
		return age > 30*24*time.Hour
	case "daily":
		return age > 10*24*time.Hour
	case "weekly":
		return age > 7*24*time.Hour
	case "yearly":
		return age > time.Hour * 24 * 365
	default:
		return false
	}
}
